contract FeeConverterVault {
    YieldToken public immutable token;
    ReservePool public immutable pool;
    uint256 public immutable referencePrice;
    uint256 public constant MAX_SINGLE = 2 ether;
    uint256 public constant TOLERANCE_BPS = 9000;
    uint256 public totalConverted;

    event Converted(uint256 amountIn, uint256 amountOut);

    constructor(address p, uint256 refPrice) payable {
        pool = ReservePool(p);
        token = ReservePool(p).token();
        referencePrice = refPrice;
    }

    function quote(uint256 amountIn) public view returns (uint256) {
        return (((amountIn * 1e18) / referencePrice) * TOLERANCE_BPS) / 10000;
    }

    function convert(uint256 amountIn) external {
        require(amountIn > 0 && amountIn <= address(this).balance, "amount");
        uint256 minOut = quote(amountIn);
        uint256 received;
        if (amountIn <= MAX_SINGLE) {
            received = pool.swapEthForToken{value: amountIn}();
        } else {
            uint256 remaining = amountIn;
            while (remaining > 0) {
                uint256 chunk = remaining > MAX_SINGLE ? MAX_SINGLE : remaining;
                received += pool.swapEthForToken{value: chunk}();
                remaining -= chunk;
            }
        }
        require(received >= minOut, "slippage");
        totalConverted += received;
        emit Converted(amountIn, received);
    }

    receive() external payable {}
}

