        sessionKey[msg.sender] = key;
        emit SessionKeyUpdated(msg.sender, key);
    }

    function withdraw(uint256 amount) external {
        require(amount > 0 && amount <= balanceOf[msg.sender], "bad amount");
        balanceOf[msg.sender] -= amount;
        totalDeposits -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
        emit Withdrawn(msg.sender, msg.sender, amount);
    }

    function withdrawDigest(address account, address to, uint256 amount) public view returns (bytes32) {
        bytes32 inner = keccak256(abi.encodePacked(address(this), account, to, amount, nonces[account]));
        return keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", inner));
    }

    function withdrawWithSession(address account, address to, uint256 amount, uint8 v, bytes32 r, bytes32 s)
        external
    {
        require(to != address(0), "bad destination");
        require(amount > 0 && amount <= balanceOf[account], "bad amount");
        address recovered = ecrecover(withdrawDigest(account, to, amount), v, r, s);
        require(recovered != address(0) && recovered == sessionKey[account], "not authorized");
        nonces[account] += 1;
        balanceOf[account] -= amount;
        totalDeposits -= amount;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "transfer failed");
        emit Withdrawn(account, to, amount);
    }
}

