        return uint256(keccak256(abi.encodePacked(blockhash(b.placedAt), block.timestamp, b.player)));
    }

    function placeBet(uint8 side) external payable returns (uint256 id) {
        require(side < 2, "bad side");
        require(msg.value > 0 && msg.value <= MAX_STAKE, "bad stake");
        require(houseLiquidity >= msg.value, "house cannot cover");
        houseLiquidity -= msg.value;
        id = bets.length;
        bets.push(Bet(msg.sender, uint96(msg.value), uint64(block.number), side, false));
        emit BetPlaced(id, msg.sender, uint96(msg.value), side);
    }

    function settle(uint256 id) external {
        Bet storage b = bets[id];
        require(!b.settled, "already settled");
