            (bool ok, ) = b.player.call{value: pot}("");
            require(ok, "payout failed");
            emit BetSettled(id, b.player, true, pot);
        } else {
            houseLiquidity += pot;
            emit BetSettled(id, b.player, false, 0);
        }
    }
}

